#!/usr/bin/env bash
# Fully generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
#
# Self-test for tests/check_pr_queue.sh. A stub `gh` answers `pr list` and
# `pr view` from files, so the row shape, the single `UNKNOWN` re-read, and the
# two unfinished-snapshot FAILs are pinned offline. The stub dispatches on the
# `list`/`view` verb and answers `view` per PR number, which is what makes the
# re-read case distinguishable from a first-pass value.
#
# Exit codes: 0 all cases pass, 1 a case mismatched, 2 setup failed.
set -u

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
GATE="$ROOT/tests/check_pr_queue.sh"
[ -f "$GATE" ] || { echo "self-test: gate not found at $GATE" >&2; exit 2; }

if command -v cygpath >/dev/null 2>&1 && [ -n "${USERPROFILE:-}" ]; then
    tmpbase=$(cygpath -w "$USERPROFILE/AppData/Local/Temp")
else
    tmpbase="${TMPDIR:-/tmp}"
fi
SANDBOX="$(mktemp -d "$tmpbase/pime-pr-queue-selftest.XXXXXX")" || {
    echo "self-test: no sandbox" >&2; exit 2; }
trap 'rm -rf "$SANDBOX"' EXIT

cat >"$SANDBOX/gh" <<'STUB'
#!/usr/bin/env bash
verb=${2:-}
case "$verb" in
    list) [ -f "${STUB_LIST:-}" ] && cat "$STUB_LIST"; exit 0 ;;
    view)
        num=${3:-}
        [ -f "${STUB_VIEW:-}" ] || exit 0
        awk -v n="$num" '$1 == n { print $2; found = 1; exit } END { if (!found) print "UNKNOWN" }' \
            "$STUB_VIEW"
        exit 0 ;;
esac
exit 0
STUB

failures=0
check() { # name want got
    if [ "$2" = "$3" ]; then
        printf 'ok    %s (rc %s)\n' "$1" "$3"
    else
        printf 'FAIL  %s: want rc %s, got rc %s\n' "$1" "$2" "$3"
        failures=$((failures + 1))
    fi
}

run_gate() {
    ( cd "$ROOT" && PATH="$SANDBOX:$PATH" STUB_LIST="$SANDBOX/list" STUB_VIEW="$SANDBOX/view" \
        bash "$GATE" EasyIME/PIME ) >/dev/null 2>&1
    printf '%s' "$?"
}

# 1. A complete snapshot: two PRs, one with no check reported yet.
printf '1029|2cfae129abcd|MERGEABLE|SUCCESS,SUCCESS\n881|948f8db0ffff|MERGEABLE|\n' \
    >"$SANDBOX/list"
: >"$SANDBOX/view"
check "complete snapshot" 0 "$(run_gate)"

# 2. A row whose head SHA is missing: the truncated-field class of miss.
printf '1029||MERGEABLE|SUCCESS\n' >"$SANDBOX/list"
check "row without a head SHA" 1 "$(run_gate)"

# 3. A first-pass UNKNOWN the single re-read settles.
printf '898|d950d61b|UNKNOWN|FAILURE,FAILURE\n' >"$SANDBOX/list"
printf '898 CONFLICTING\n' >"$SANDBOX/view"
check "UNKNOWN settled by the re-read" 0 "$(run_gate)"

# 4. An UNKNOWN that survives the re-read: an unsettled disposition.
printf '898 UNKNOWN\n' >"$SANDBOX/view"
check "UNKNOWN after the re-read" 1 "$(run_gate)"

# 5. No `gh` on this box: not applicable.
( cd "$ROOT" && GH_BIN=pime-no-such-gh bash "$GATE" EasyIME/PIME ) >/dev/null 2>&1
check "no gh on PATH" 125 "$?"

# 6. The repo answers nothing at all: not applicable, not red.
: >"$SANDBOX/list"
check "empty queue" 125 "$(run_gate)"

if [ "$failures" -ne 0 ]; then
    printf 'Self-test failed (%d case(s))\n' "$failures" >&2
    exit 1
fi
echo "Self-test passed"
